const{chromium}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs');
(async()=>{const b=await chromium.launch({channel:'chrome'});try{const p=await b.newPage({viewport:{width:1600,height:900}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ROCKET_BASE||((process.env.TEST_ORIGIN||'http://127.0.0.1:9036')+'/experiments/rocket-launch/'));
const cases=await p.evaluate(async()=>{const {createVelocityScene}=await import('./velocity.js');const cases=[];for(const height of [1000,10000,100000])for(const speed of [.5,1,4.5,6.5]){const canvas=document.createElement('canvas');canvas.width=1500;canvas.height=650;const ctx=canvas.getContext('2d'),scene=createVelocityScene();scene.setHeight(height);scene.setValue(speed);scene.state.age=5;scene.draw(ctx,1500,650,0);const q=scene.state.presentation,x=Math.round(q.projectile[0]),y=Math.round(q.projectile[1]),pixel=Array.from(ctx.getImageData(x,y,1,1).data),ground=Array.from(ctx.getImageData(x+18,y,1,1).data);cases.push({height,speed,...q,pixel,ground});}return cases;});
for(const c of cases){assert(c.landed);assert(Math.abs(c.projectile[1]-c.groundY)<1e-6);assert(c.pixel[0]>180&&c.pixel[1]>120&&c.pixel[2]<160&&c.pixel[3]>200);assert(c.ground[3]>0);assert(c.rangeKm>0);assert(c.rangeStart[0]<c.rangeEnd[0]);assert.equal(c.rangeEnd[0],c.projectile[0]);}
await p.locator('#chapters>button').nth(1).click();assert.equal(await p.evaluate(()=>RocketModel.scene.state.height),100000);assert.equal(await p.locator('.cannon-height-options').count(),0);for(const speed of ['1','4.5']){if(speed!=='1')await p.locator('#velocity-adjust').click();await p.locator('#velocity-speed').fill(speed);await p.locator('#velocity-fire').click();assert.equal(await p.locator('#velocity-preset-axis').isVisible(),false);await p.waitForFunction(()=>RocketModel.scene.state.paused&&RocketModel.scene.state.age>=5&&RocketModel.scene.state.presentation?.landed,{},{timeout:8000});const q=await p.evaluate(()=>RocketModel.scene.state.presentation);assert(Math.abs(q.projectile[1]-q.groundY)<1e-6);await p.screenshot({path:__dirname+'/docs/review-20261115/cannon-landed-'+speed+'.png'});}
assert.deepEqual(errors,[]);fs.writeFileSync(__dirname+'/docs/review-20261115/cannon-ground-results.json',JSON.stringify({pass:true,cases,errors},null,2));console.log('PASS 12 height/speed render cases: projectile pixel on ground, real UI 1/4.5 km/s landings, explicit muzzle-height label, hidden speed choices during flight');
}finally{await b.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
